import java.util.concurrent.*;

public class Main {
    static void run(String name, BlockingQueue<Runnable> queue) throws Exception {
        CountDownLatch hold = new CountDownLatch(1);
        // core=2, max=4; tasks block until the latch opens so the pool stays busy
        ThreadPoolExecutor pool = new ThreadPoolExecutor(
            2, 4, 1, TimeUnit.SECONDS, queue, new ThreadPoolExecutor.AbortPolicy());
        System.out.println(name);
        for (int i = 1; i <= 7; i++) {
            try {
                pool.execute(() -> {
                    try { hold.await(); } catch (InterruptedException e) { }
                });
                System.out.println("task " + i + ": threads=" + pool.getPoolSize()
                    + " queued=" + pool.getQueue().size());
            } catch (RejectedExecutionException e) {
                System.out.println("task " + i + ": REJECTED");
            }
        }
        hold.countDown();
        pool.shutdown();
        pool.awaitTermination(2, TimeUnit.SECONDS);
    }

    public static void main(String[] args) throws Exception {
        // bounded queue of 2: core fills, then queue, then extra threads, then reject
        run("bounded queue (capacity 2)", new ArrayBlockingQueue<>(2));
        // unbounded queue never fills, so the pool never grows past core
        run("unbounded queue", new LinkedBlockingQueue<>());
    }
}

