// Load shedding with a concurrency limit: reject instantly when full.
// Capacity: 3 requests in flight; the 4th..6th get a fast "503".
const LIMIT = 3;
let inFlight = 0;
let served = 0, shed = 0;

function handle(id) {
  if (inFlight >= LIMIT) {            // cheap check before any real work
    shed++;
    console.log(`request ${id}: 503 Service Unavailable (Retry-After: 1)`);
    return Promise.resolve();
  }
  inFlight++;                         // take a slot
  console.log(`request ${id}: accepted (in flight ${inFlight})`);
  return new Promise(res => setTimeout(res, 50)).then(() => {
    inFlight--;                       // free the slot
    served++;
  });
}

async function main() {
  const batch = [];
  for (let i = 1; i <= 6; i++) batch.push(handle(i));   // burst of 6
  await Promise.all(batch);
  console.log(`burst 1: served=${served} shed=${shed}`);
  await handle(7);                    // after the burst slots are free again
  console.log(`later request served, total served=${served}`);
}
main();

// Circuit breaker: closed -> open -> half-open -> closed.
class Breaker {
  constructor(threshold, coolDown) {
    this.threshold = threshold; this.coolDown = coolDown;
    this.state = "CLOSED"; this.failures = 0; this.openedAt = 0;
  }
  call(fn, now) {
    if (this.state === "OPEN") {
      if (now - this.openedAt < this.coolDown) return "rejected fast";
      this.state = "HALF_OPEN";               // cool-down over: probe once
    }
    try {
      const r = fn();
      this.state = "CLOSED"; this.failures = 0;  // success closes it
      return r;
    } catch (e) {
      this.failures++;
      if (this.state === "HALF_OPEN" || this.failures >= this.threshold) {
        this.state = "OPEN"; this.openedAt = now;  // trip
      }
      return "failed";
    }
  }
}

let dependencyUp = false;
const dep = () => { if (!dependencyUp) throw new Error("down"); return "ok"; };
const b = new Breaker(3, 100);
for (const t of [0, 10, 20, 30, 40, 50]) {
  console.log(`t=${t} -> ${b.call(dep, t)} [${b.state}]`);
}
dependencyUp = true;                       // dependency recovers
for (const t of [120, 130]) {
  console.log(`t=${t} -> ${b.call(dep, t)} [${b.state}]`);
}
